class TableParser(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True); self.tables=[]; self.table=None; self.row=None; self.cell=None; self.in_table=False; self.in_cell=False
    def handle_starttag(self, tag, attrs):
        if tag == "table": self.in_table=True; self.table=[]
        elif self.in_table and tag == "tr": self.row=[]
        elif self.in_table and self.row is not None and tag in ("td","th"): self.in_cell=True; self.cell=[]
    def handle_data(self, data):
        if self.in_cell and self.cell is not None: self.cell.append(data)
    def handle_endtag(self, tag):
        if self.in_table and tag in ("td","th") and self.in_cell:
            self.row.append(" ".join("".join(self.cell).replace("\xa0"," ").split())); self.cell=None; self.in_cell=False
        elif self.in_table and tag == "tr" and self.row is not None:
            if self.row: self.table.append(self.row)
            self.row=None
        elif tag == "table" and self.in_table:
            if self.table: self.tables.append(self.table)
            self.table=None; self.in_table=False

def now_utc(): return datetime.now(timezone.utc).isoformat()
def parse_date(text):
    try: return datetime.strptime(text.strip(), "%d %b %Y").date().isoformat()
    except Exception: return None
def expected_dates(start,end): return [d for d in XNYS_SESSIONS if start <= d <= end]

def main():
    summary={"scope":"FARSIDE_BTC_HISTORY_COMPLETENESS_EXACT_PUBLIC_TABLE_AUDIT","source_url":URL,"retrieved_at_utc":now_utc(),"transport":"ordinary-system-chrome-direct-browser","proxy_used":False,"stealth_used":False,"challenge_bypass_used":False,"secrets_used":False,"http_status":None,"artifact_sha256":None,"response_last_modified":None,"response_date":None,"table_last_date":None,"columns":[],"funds":{},"error":None}
    try:
        chrome="/usr/bin/google-chrome"
        with sync_playwright() as p:
            browser=p.chromium.launch(headless=True,executable_path=chrome); page=browser.new_page(locale="en-US")
            nav=page.goto(URL,wait_until="domcontentloaded",timeout=35000); summary["http_status"]=nav.status if nav else None; page.wait_for_timeout(3000); html=page.content(); browser.close()
        body=html.encode("utf-8")
        if len(body)>MAX_BYTES: raise RuntimeError("FARSIDE_BODY_TOO_LARGE")
        summary["artifact_sha256"]=hashlib.sha256(body).hexdigest(); (OUT/"farside-btc-all-data.html").write_bytes(body)
        parser=TableParser(); parser.feed(html); target=None
        for table in parser.tables:
            if table and {"Date","IBIT","FBTC","BITB","ARKB","GBTC"}.issubset(set(c.strip() for c in table[0])): target=table; break
        if target is None: raise RuntimeError("FARSIDE_TARGET_TABLE_NOT_FOUND")
        header=target[0]; summary["columns"]=header; index={name:i for i,name in enumerate(header)}; rows={}
        for raw in target[1:]:
            if not raw: continue
            iso=parse_date(raw[index["Date"]] if len(raw)>index["Date"] else "")
            if not iso: continue
            rows[iso]={name:(raw[idx].strip() if idx<len(raw) else "") for name,idx in index.items()}
        if not rows: raise RuntimeError("FARSIDE_NO_DATED_ROWS")
        summary["table_last_date"]=max(rows)
        for ticker,(start,end) in SCOPES.items():
            expected=expected_dates(start,end)
            if ticker not in index:
                summary["funds"][ticker]={"history_scope_start":start,"history_scope_end":end,"required_trading_dates":len(expected),"farside_column":False,"covered_trading_dates":0,"missing_trading_dates":len(expected),"missing_dates":expected,"explicit_dash_dates":[],"absent_row_dates":expected,"status":"FARSIDE_COLUMN_ABSENT"}; continue
            covered=[]; explicit_dash=[]; absent=[]; missing=[]
            for d in expected:
                row=rows.get(d)
                if row is None: absent.append(d); missing.append(d); continue
                value=(row.get(ticker) or "").strip()
                if value in ("","-","–","—"): explicit_dash.append(d); missing.append(d)
                else: covered.append(d)
            summary["funds"][ticker]={"history_scope_start":start,"history_scope_end":end,"required_trading_dates":len(expected),"farside_column":True,"covered_trading_dates":len(covered),"missing_trading_dates":len(missing),"missing_dates":missing,"explicit_dash_dates":explicit_dash,"absent_row_dates":absent,"first_covered_date":covered[0] if covered else None,"last_covered_date":covered[-1] if covered else None,"status":"FARSIDE_PUBLIC_TABLE_COMPLETE_FOR_SCOPE" if not missing else "FARSIDE_PUBLIC_TABLE_HAS_GAPS"}
        summary["finished_at_utc"]=now_utc(); (OUT/"summary.json").write_text(json.dumps(summary,indent=2),encoding="utf-8")
        print(f"FARSIDE_HTTP={summary['http_status']}"); print(f"FARSIDE_TABLE_LAST_DATE={summary['table_last_date']}"); print("FARSIDE_COLUMNS="+",".join(summary["columns"]))
        for ticker in SCOPES:
            row=summary["funds"][ticker]; first=row["missing_dates"][0] if row["missing_dates"] else "NONE"; last=row["missing_dates"][-1] if row["missing_dates"] else "NONE"
            print(f"{ticker} required={row['required_trading_dates']} covered={row['covered_trading_dates']} missing={row['missing_trading_dates']} first_missing={first} last_missing={last} status={row['status']}")
        print("FARSIDE_AUDIT_ERROR=None")
    except Exception as exc:
        summary["error"]=f"{type(exc).__name__}:{exc}"; summary["finished_at_utc"]=now_utc(); (OUT/"summary.json").write_text(json.dumps(summary,indent=2),encoding="utf-8"); print("FARSIDE_AUDIT_ERROR="+summary["error"]); raise

if __name__=="__main__": main()
